// Retry taxonomy — mirrors lib/ops/retry.ts, which is the tested specification.
const RETRYABLE = new Set(['network_timeout','dns_failure','connection_reset','http_408','http_429','http_500','http_502','http_503','http_504','db_connection_failure','ai_provider_unavailable','ai_rate_limited','storage_unavailable']);

const isRetryable = (code) => RETRYABLE.has(code);

const codeForHttpStatus = (s) => {
  if (s === 408) return 'http_408';
  if (s === 429) return 'http_429';
  if ([500,502,503,504].includes(s)) return 'http_' + s;
  if (s >= 500) return 'http_500';
  if (s === 401) return 'http_401';
  if (s === 403) return 'http_403';
  if (s === 404) return 'http_404';
  if (s === 410) return 'http_410';
  if (s >= 400) return 'http_400';
  return 'ok';
};

// Exponential backoff WITH JITTER. Without jitter a batch of sources that
// failed together would retry in lockstep forever, keeping the herd
// synchronised on whatever upstream knocked them over.
const backoffMs = (attempt, schedule) => {
  const s = (schedule && schedule.length) ? schedule : [5,15,45,120,360];
  const base = (s[Math.min(Math.max(attempt,1), s.length) - 1] || 5) * 60000;
  const spread = base * 0.2;
  return Math.max(1000, Math.round(base + (Math.random() * 2 - 1) * spread));
};

// ── RETRY SWEEP ────────────────────────────────────────────────────────────
// Runs every 15 minutes. Finds sources whose backoff has elapsed and decides,
// per source, whether another attempt is warranted or the job is dead.
//
// Idempotent: it only ever moves a source forward — either scheduling the next
// attempt or marking it dead. It never re-enqueues an item already published,
// because the Publishing Gate's hash check runs on every path.

const all = $input.all().map(i => i.json);
const settings = all.filter(r => typeof r.key === 'string');
const sources  = all.filter(r => typeof r.base_url === 'string');

const setting = (key, fallback) => {
  const row = settings.find(r => r.key === key);
  return row && row.value !== null && row.value !== undefined ? row.value : fallback;
};

const schedule = setting('ingestion.retry_backoff_minutes', [5,15,45,120,360]);
const maxAttempts = Array.isArray(schedule) ? schedule.length : 5;
const now = Date.now();

const toRetry = [];
const toKill = [];

for (const s of sources) {
  if (!s.active || s.config_status !== 'verified') continue;
  if (s.retry_attempt <= 0) continue;
  if (!s.next_retry_at || new Date(s.next_retry_at).getTime() > now) continue;

  const code = s.last_error_code || 'unknown_error';

  // A permanent error is not retried at all, however many attempts remain.
  // Retrying a 404 or a selector mismatch cannot succeed and only delays the
  // moment somebody notices.
  if (!isRetryable(code)) {
    toKill.push({ json: { source: s, reason: 'permanent_error', error_code: code } });
    continue;
  }

  if (s.retry_attempt >= maxAttempts) {
    toKill.push({ json: { source: s, reason: 'max_attempts_exhausted', error_code: code } });
    continue;
  }

  const next = s.retry_attempt + 1;
  toRetry.push({ json: {
    source: s,
    trigger_type: 'retry',
    dispatched_at: new Date().toISOString(),
    attempt_number: next,
    max_attempts: maxAttempts,
    next_backoff_ms: backoffMs(next, schedule),
  }});
}

console.log(JSON.stringify({ stage: 'retry_sweep', retrying: toRetry.length, dead: toKill.length }));
return [...toRetry, ...toKill];

// ── DEAD LETTER ────────────────────────────────────────────────────────────
// Builds the dead-letter row for a job that will not be retried again.
//
// The payload is written WITHOUT credentials: parser_config.headers can carry
// an API key for an authenticated feed, so it is stripped here. A CHECK
// constraint on the table rejects credential-shaped keys as a backstop.

const out = [];
for (const entry of $input.all()) {
  const e = entry.json;
  if (!e.reason) continue;               // this branch only handles deaths
  const s = e.source;

  const cfg = { ...(s.parser_config || {}) };
  delete cfg.headers;                    // never persist auth headers
  delete cfg.authorization;
  delete cfg.api_key;

  out.push({ json: {
    source_id: s.id,
    stage: 'fetch',
    item_url: s.feed_url || s.base_url,
    content_hash: null,
    error_code: e.error_code,
    error_message: (s.last_failure_reason || '').slice(0, 1000) || null,
    attempt_number: s.retry_attempt || 0,
    max_attempts: 5,
    first_attempt_at: s.first_attempt_at || null,
    last_attempt_at: s.last_failure_at || new Date().toISOString(),
    workflow_execution_id: String($execution.id),
    payload: { authority_ar: s.authority_ar, base_url: s.base_url, parser_type: s.parser_type, parser_config: cfg },
    state: 'open',
  }});
}
return out;

// ── HEALTH SNAPSHOT ────────────────────────────────────────────────────────
// Mirrors lib/ops/health.ts, which is the tested specification.
//
// Health measures whether the platform can RETRIEVE AND PROCESS a source.
// Duplicates, gate rejections on the merits, and empty runs NEVER reduce the
// score — a ministry that published nothing this week is quiet, not broken,
// and a dashboard that says otherwise trains people to ignore it.

const all = $input.all().map(i => i.json);
const settings = all.filter(r => typeof r.key === 'string');
const sources  = all.filter(r => typeof r.base_url === 'string');
const logs     = all.filter(r => typeof r.workflow_name === 'string');
const deads    = all.filter(r => typeof r.error_code === 'string' && r.state === 'open');

const setting = (key, fb) => {
  const row = settings.find(r => r.key === key);
  return row && row.value !== null && row.value !== undefined ? row.value : fb;
};

const failThreshold = Number(setting('ingestion.failure_alert_threshold', 5));
const defaultSilence = Number(setting('health.stale_after_minutes', 1440));
const cooldownMinutes = 180;
const now = Date.now();
const ratio = (n, d) => (d <= 0 ? null : Math.min(1, Math.max(0, n / d)));

const snapshots = [];
const alerts = [];

for (const s of sources) {
  const runs = logs.filter(l => l.source_id === s.id);
  const deadCount = deads.filter(d => d.source_id === s.id).length;

  let fetchOk = 0, extractionOk = 0, gateAttempts = 0, gateAccepted = 0, dupes = 0, durationTotal = 0;
  let aiAttempts = 0, aiOk = 0, lastItemFoundAt = null;

  for (const l of runs) {
    durationTotal += l.duration_ms || 0;
    if (l.status !== 'failed') fetchOk += 1;
    if ((l.items_fetched || 0) > 0) extractionOk += 1;

    const reasons = l.rejection_reasons || {};
    const aiFailures = (reasons.ai_parse_failure || 0) + (reasons.ai_invalid_output || 0);
    const items = (l.items_published || 0) + (l.items_rejected || 0);
    aiAttempts += items;
    aiOk += Math.max(0, items - aiFailures);

    gateAttempts += items;
    gateAccepted += l.items_published || 0;
    dupes += reasons.duplicate || 0;

    if ((l.items_published || 0) > 0 && (!lastItemFoundAt || l.started_at > lastItemFoundAt)) {
      lastItemFoundAt = l.started_at;
    }
  }

  const rates = {
    fetch: ratio(fetchOk, runs.length),
    extraction: ratio(extractionOk, fetchOk),
    ai: ratio(aiOk, aiAttempts),
    gate: ratio(gateAccepted, gateAttempts),
    dupe: ratio(dupes, gateAttempts),
  };

  const neverChecked = !s.last_run_at;
  const everSucceeded = !!s.last_success_at;
  const silence = s.max_silence_minutes || defaultSilence;

  // Staleness is measured from the last SUCCESSFUL CHECK, not the last item —
  // a source polled successfully that simply has nothing to say is healthy.
  const stale = everSucceeded && (now - new Date(s.last_success_at).getTime()) > silence * 60000;

  let score = 100;
  score -= Math.min(60, (s.consecutive_failures || 0) * 15);
  if (rates.fetch !== null) score -= (1 - rates.fetch) * 30;
  if (rates.extraction !== null) score -= (1 - rates.extraction) * 20;
  if (rates.ai !== null) score -= (1 - rates.ai) * 15;
  if (stale) score -= 20;
  if (deadCount > 0) score -= Math.min(15, deadCount * 5);
  score = Math.max(0, Math.min(100, Math.round(score)));

  let classification;
  if (!s.active) classification = 'disabled';
  else if (s.config_status !== 'verified') classification = 'unverified';
  else if (neverChecked) classification = 'never_run';
  else if ((s.consecutive_failures || 0) >= failThreshold || score < 40) classification = 'failing';
  else if ((s.consecutive_failures || 0) > 0 || score < 70) classification = 'degraded';
  else if (stale) classification = 'stale';
  else classification = 'healthy';

  snapshots.push({ json: {
    __kind: 'snapshot',
    source_id: s.id,
    classification,
    health_score: score,
    enabled: !!s.active,
    verified: s.config_status === 'verified',
    stale,
    last_checked_at: s.last_run_at,
    last_success_at: s.last_success_at,
    last_item_found_at: lastItemFoundAt,
    consecutive_failures: s.consecutive_failures || 0,
    dead_job_count: deadCount,
    window_runs: runs.length,
    fetch_success_rate: rates.fetch,
    extraction_success_rate: rates.extraction,
    ai_success_rate: rates.ai,
    gate_acceptance_rate: rates.gate,
    duplicate_rate: rates.dupe,
    avg_response_ms: runs.length ? Math.round(durationTotal / runs.length) : null,
    last_http_status: s.last_http_status || null,
    last_error_code: s.last_error_code || null,
    last_error_message: s.last_failure_reason || null,
  }});

