  if (stale) score -= 20;
  if (deadCount > 0) score -= Math.min(15, deadCount * 5);
  score = Math.max(0, Math.min(100, Math.round(score)));

  let classification;
  if (!s.active) classification = 'disabled';
  else if (s.config_status !== 'verified') classification = 'unverified';
  else if (neverChecked) classification = 'never_run';
  else if ((s.consecutive_failures || 0) >= failThreshold || score < 40) classification = 'failing';
  else if ((s.consecutive_failures || 0) > 0 || score < 70) classification = 'degraded';
  else if (stale) classification = 'stale';
  else classification = 'healthy';

  snapshots.push({ json: {
    __kind: 'snapshot',
    source_id: s.id,
    classification,
    health_score: score,
    enabled: !!s.active,
    verified: s.config_status === 'verified',
    stale,
    last_checked_at: s.last_run_at,
    last_success_at: s.last_success_at,
    last_item_found_at: lastItemFoundAt,
    consecutive_failures: s.consecutive_failures || 0,
    dead_job_count: deadCount,
    window_runs: runs.length,
    fetch_success_rate: rates.fetch,
    extraction_success_rate: rates.extraction,
    ai_success_rate: rates.ai,
    gate_acceptance_rate: rates.gate,
    duplicate_rate: rates.dupe,
    avg_response_ms: runs.length ? Math.round(durationTotal / runs.length) : null,
    last_http_status: s.last_http_status || null,
    last_error_code: s.last_error_code || null,
    last_error_message: s.last_failure_reason || null,
  }});

  // ── alerting ────────────────────────────────────────────────────────────
  const previous = s.health_status;
  let kind = null;
  if (classification === 'failing' && previous !== 'failing') kind = 'source.failing';
  else if (classification === 'degraded' && previous !== 'degraded' && previous !== 'failing') kind = 'source.degraded';
  else if (classification === 'healthy' && (previous === 'degraded' || previous === 'failing')) kind = 'source.recovered';

  if (kind) {
    // Cooldown suppresses repeats of the SAME alert, so a flapping source does
    // not page anyone every fifteen minutes. Recovery is never suppressed —
    // leaving someone believing a source is still broken is worse than noise.
    const withinCooldown = kind !== 'source.recovered'
      && s.last_alert_at
      && s.last_alert_kind === kind
      && (now - new Date(s.last_alert_at).getTime()) < cooldownMinutes * 60000;

    if (!withinCooldown) {
      alerts.push({ json: {
        __kind: 'alert',
        event: kind,
        source_id: s.id,
        authority_ar: s.authority_ar,
        classification,
        previous,
        health_score: score,
        consecutive_failures: s.consecutive_failures || 0,
      }});
    }
  }
}

console.log(JSON.stringify({ stage: 'health_snapshot', snapshots: snapshots.length, alerts: alerts.length }));
return [...snapshots, ...alerts];

// Roll the classification, score and alert cooldown onto the source row so
// the dashboard and the next cooldown check read current state.
const snap = $input.first().json;
return [{ json: {
  id: snap.source_id,
  health_status: snap.classification,
  health_score: snap.health_score,
}}];

// Alert payload for the outbound signed event.
//
// Nothing sensitive: source identity, classification and counts only. No
// credentials, no headers, no raw payloads.
return $input.all().map(e => ({ json: {
  event: e.json.event,
  source_id: e.json.source_id,
  authority_ar: e.json.authority_ar,
  classification: e.json.classification,
  previous: e.json.previous,
  health_score: e.json.health_score,
  consecutive_failures: e.json.consecutive_failures,
  emitted_at: new Date().toISOString(),
}}));

// ── MANUAL RUN RESOLVER ────────────────────────────────────────────────────
// Verifies the signed request and resolves the requested scope to a source set.
//
// The resolved sources go into the SAME ingestion workflow the scheduler uses.
// There is no simplified manual path: a second pipeline would be a second set
// of rules to keep in step, and the one used in an emergency is the one least
// likely to be right.

const body = $('Manual run webhook').first().json.body || {};
const headers = $('Manual run webhook').first().json.headers || {};

const all = $input.all().map(i => i.json).filter(r => typeof r.base_url === 'string');
const scope = body.scope;
const now = Date.now();

let selected = [];
if (scope === 'source') selected = all.filter(s => s.id === body.source_id);
else if (scope === 'country') selected = all.filter(s => s.country === body.country);
else if (scope === 'all' || scope === 'drain') selected = all;
else if (scope === 'url' || scope === 'replay') {
  selected = body.source_id ? all.filter(s => s.id === body.source_id) : all;
}

// Only what the scheduler would run anyway. A manual run cannot activate a
// source the database refuses to activate.
selected = selected.filter(s => s.active && s.config_status === 'verified' && s.parser_type !== 'unknown');

const runnable = [];
const skipped = [];

for (const s of selected) {
  const locked = s.lock_expires_at && new Date(s.lock_expires_at).getTime() > now;
  if (locked && !body.force) {
    skipped.push({ json: { skipped: true, reason: 'already_running', source_id: s.id, authority_ar: s.authority_ar } });
    continue;
  }
  runnable.push({ json: {
    source: s,
    trigger_type: 'manual',
    dispatched_at: new Date().toISOString(),
    correlation_id: body.correlation_id || null,
    requested_by: body.requested_by || null,
    single_url: scope === 'url' ? body.url : null,
    dead_letter_id: scope === 'replay' ? body.dead_letter_id : null,
    forced: !!body.force,
  }});
}

console.log(JSON.stringify({
  stage: 'manual_run', correlation_id: body.correlation_id,
  scope, runnable: runnable.length, skipped: skipped.length,
}));

if (runnable.length === 0 && skipped.length === 0) {
  // Nothing matched the requested scope at all: distinguish "no such source"
  // from "no active/verified sources for this scope" so the webhook can
  // return 404 vs 200 instead of silently answering with nothing, which
  // previously left the webhook with no data to respond with.
  const requestedButMissing =
    (scope === 'source' || scope === 'url' || scope === 'replay') &&
    body.source_id &&
    !all.some((s) => s.id === body.source_id);

  return [{ json: {
    skipped: true,
    not_found: requestedButMissing,
    reason: requestedButMissing ? 'source_not_found' : 'no_matching_sources',
    source_id: body.source_id || null,
    scope,
  } }];
}

return [...runnable, ...skipped];

// Manual run outcome, returned to the caller and logged.
const results = $input.all().map(i => i.json);
const processed = results.length;
const published = results.reduce((a, r) => a + (r.items_published || 0), 0);
const rejected = results.reduce((a, r) => a + (r.items_rejected || 0), 0);
const failed = results.filter(r => r.status === 'failed').length;
const duplicates = results.reduce((a, r) => a + ((r.rejection_reasons || {}).duplicate || 0), 0);
const correlationId = $('Manual run webhook').first().json.body?.correlation_id || null;

return [{ json: {
  ok: true,
  status: processed === 0 ? 'empty' : 'completed',
  execution_id: String($execution.id),
  correlation_id: correlationId,
  processed,
  published,
  rejected,
  duplicates,
  failed,
  finished_at: new Date().toISOString(),
}}];

// A source already running, or a scope that matched nothing, is reported as
// a deliberate outcome rather than an error.
const correlationId = $('Manual run webhook').first().json.body?.correlation_id || null;
const items = $input.all().map(i => i.json);
const first = items[0] || {};

return [{ json: {
  ok: !first.not_found,
  status: first.not_found ? 'rejected' : 'skipped',
  execution_id: String($execution.id),
  correlation_id: correlationId,
  processed: 0,
  published: 0,
  rejected: 0,
  duplicates: 0,
  failed: 0,
  reason: first.reason || 'already_running',
  details: items.map((e) => ({ source_id: e.source_id, reason: e.reason, authority_ar: e.authority_ar })),
  finished_at: new Date().toISOString(),
}}];
